<?php
require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/helpers.php'; require_role(['Supervisor','HR Admin','Admin']); $pdo=db(); $title='Employee Request';$rows=$pdo->query("SELECT r.*,e.employee_code,e.full_name,e.department FROM item_requests r JOIN employees e ON e.id=r.employee_id ORDER BY (r.status='Pending') DESC,r.id DESC")->fetchAll();require __DIR__.'/../includes/header.php';?>
<div class="page-head"><div><h2>Employee Request</h2><p>Review employee requests and current status.</p></div></div><div class="card"><h3>Employee requests (<?=count($rows)?>)</h3><div class="table-wrap"><table><tr><th>Employee</th><th>Department</th><th>Request</th><th>Qty</th><th>Reason</th><th>Status</th><th>Created</th></tr><?php if(!$rows):?><tr><td colspan="7">No employee requests found.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['employee_code'].' — '.$r['full_name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['item_name'])?></td><td><?=(int)$r['quantity']?></td><td><?=e($r['reason']??'')?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>